'use strict';
const $=id=>document.getElementById(id), key='ghost-ui-demo-v1';
const palette=['#292929','#858585','#A3835D','#E89042','#D1B348','#418D79','#49ABAD','#438ECE','#7765CF','#DD709E','#DC4C5C','#536B85'];
const defaultBots=[['Chief of Staff','chief','Working...'],['Developer','developer','Ready'],['Researcher','researcher','Ready'],['Email Assistant','automation','Scheduled'],['Daily Assistant','assistant','Ready']].map(([name,shape,status],i)=>({id:'bot'+i,name,status,instructions:'',avatar:{shape,color:PRESETS.find(p=>p.id===shape).color,eyes:'classic',rotation:0,animation:true},messages:[],model:'GPT-6.2 (demo)',effort:'Medium',permission:'Ask approval'}));
let saved;try{saved=JSON.parse(localStorage.getItem(key)||'null')}catch{};
let state=saved&&Array.isArray(saved.bots)&&saved.bots.length?saved:{bots:defaultBots,active:'bot0',theme:'Dark',font:'Default',approval:'pending'};
const persist=()=>{try{localStorage.setItem(key,JSON.stringify(state))}catch{}};
const current=()=>state.bots.find(b=>b.id===state.active)||state.bots[0];
const escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function avatar(a,status='idle',size=32){const p=PRESETS.find(x=>x.id===a.shape)||PRESETS[0];const color=/^#[0-9a-f]{6}$/i.test(a.color)?a.color:p.color;const tilt=Math.max(-20,Math.min(20,Number(a.rotation)||0));const eye=a.eyes==='happy'?'<path d="M22 37 Q28 24 34 37 M44 37 Q50 24 56 37" fill="none" stroke="white" stroke-width="4" stroke-linecap="round"/>':a.eyes==='round'?'<circle cx="28" cy="34" r="4.5" fill="white"/><circle cx="50" cy="34" r="4.5" fill="white"/>':a.eyes==='sleepy'?'<rect x="22" y="34" width="12" height="3" rx="1.5" fill="white"/><rect x="44" y="34" width="12" height="3" rx="1.5" fill="white"/>':'<rect x="25" y="28" width="6.5" height="14" rx="3.25" fill="white"/><rect x="47" y="26" width="6.5" height="14" rx="3.25" fill="white"/>';return `<svg class="avatar ${a.animation?status:''}" viewBox="0 0 80 80" width="${size}" height="${size}" aria-hidden="true"><g class="body"><g transform="rotate(${tilt} 40 40)"><path d="${p.path}" fill="${color}"/><g class="eyes">${eye}</g></g></g></svg>`}
const models={'GPT-6.2 (demo)':['Low','Medium','High','Extra High'],'Claude (demo)':['Low','Medium','High'],'Gemini (demo)':['Default','High'],'Kimi (demo)':['Default'],'Ollama (demo)':['Default']};
function options(el,values,selected){el.replaceChildren(...values.map(v=>new Option(v,v)));el.value=values.includes(selected)?selected:values[0]}
function renderBots(){const q=$('search').value.toLowerCase();$('bots').innerHTML=state.bots.filter(b=>b.name.toLowerCase().includes(q)).map(b=>`<button class="bot ${b.id===current().id?'active':''}" data-bot="${escapeHTML(b.id)}">${avatar(b.avatar,b.status==='Working...'?'working':'idle')}<div><span>${escapeHTML(b.name)}</span><small>${escapeHTML(b.status)}</small></div></button>`).join('');$('bots').querySelectorAll('[data-bot]').forEach(el=>el.onclick=()=>{state.active=el.dataset.bot;persist();render()})}
function renderMessages(){const b=current();let html='<div class="date">Today · Demo session</div>';if(b.id==='bot0'){html+=`<div class="bubble">Review my GitHub projects and plan tomorrow's tasks.</div><div class="assistant-msg">I'll coordinate with your Developer bot and prepare a summary.</div><div class="task-card"><p><span class="success">✓</span> &nbsp; Read project files</p><p><span class="success">✓</span> &nbsp; Delegated to Developer</p><p>◌ &nbsp; Analyzing pending tasks</p></div><div class="task-card"><strong>♧ &nbsp; ${state.approval==='pending'?'Approval required':'Approval '+escapeHTML(state.approval)}</strong><p class="muted">Developer wants to edit ROADMAP.md · simulated</p><button id="reviewDiff">Review diff</button> ${state.approval==='pending'?'<button id="approve">Approve</button> <button id="deny">Deny</button>':''}</div>`}else{html+=`<div class="assistant-msg">Hi! I'm ${escapeHTML(b.name)}. This is an offline prototype; no model is connected.</div>`}html+=b.messages.map(m=>`<div class="${m.role==='user'?'bubble':'assistant-msg'}">${escapeHTML(m.text)}</div>`).join('');$('messages').innerHTML=html;if($('reviewDiff'))$('reviewDiff').onclick=()=>$('diffDialog').showModal();for(const [id,status] of [['approve','approved'],['deny','denied']])if($(id))$(id).onclick=()=>{state.approval=status;persist();renderMessages()};$('messages').scrollTop=$('messages').scrollHeight}
function render(){const b=current();renderBots();$('activeAvatar').innerHTML=avatar(b.avatar,'idle');$('activeName').textContent=b.name;$('message').placeholder='Message '+b.name+'...';options($('model'),Object.keys(models),b.model);options($('effort'),models[$('model').value],b.effort);$('permission').value=b.permission;renderMessages()}
$('search').oninput=renderBots;$('model').onchange=()=>{current().model=$('model').value;options($('effort'),models[current().model],current().effort);current().effort=$('effort').value;persist()};$('effort').onchange=()=>{current().effort=$('effort').value;persist()};$('permission').onchange=()=>{if($('permission').value==='Full Access'&&!confirm('Demo only. Full Access would require explicit opt-in in the real app. Continue?')){$('permission').value=current().permission;return}current().permission=$('permission').value;persist()};$('composer').onsubmit=e=>{e.preventDefault();const v=$('message').value.trim();if(!v)return;current().messages.push({role:'user',text:v},{role:'assistant',text:'[Offline demo] Your message was saved locally. No model, tool or subscription was invoked.'});$('message').value='';persist();renderMessages()};$('toggleLeft').onclick=()=>$('left').classList.toggle('hidden');$('toggleRight').onclick=()=>$('right').classList.toggle('hidden');document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$(b.dataset.close).close());
let editing=null,draft;
function drawEditor(){ $('avatarPreview').innerHTML=avatar(draft,'idle',105);$('shapes').innerHTML=PRESETS.map(p=>`<button type="button" title="${p.name}" class="${p.id===draft.shape?'selected':''}" data-shape="${p.id}">${avatar({...draft,shape:p.id,animation:false})}</button>`).join('');$('shapes').querySelectorAll('button').forEach(b=>b.onclick=()=>{draft.shape=b.dataset.shape;drawEditor()});$('colors').innerHTML=palette.map(c=>`<button type="button" aria-label="${c}" class="${c===draft.color?'selected':''}" data-color="${c}" style="background:${c}"></button>`).join('');$('colors').querySelectorAll('button').forEach(b=>b.onclick=()=>{draft.color=b.dataset.color;drawEditor()});$('eyes').value=draft.eyes;$('rotation').value=draft.rotation;$('animate').checked=draft.animation}
function openEditor(b){editing=b?.id||null;draft=b?{...b.avatar}:{shape:'ghost',color:'#7765CF',eyes:'classic',rotation:0,animation:true};$('botFormTitle').textContent=b?'Edit bot':'Create bot';$('botName').value=b?.name||'';$('botInstructions').value=b?.instructions||'';$('deleteBot').hidden=!b||state.bots.length===1;drawEditor();$('botDialog').showModal()}
$('newBot').onclick=()=>openEditor(null);$('editBot').onclick=()=>openEditor(current());$('eyes').onchange=()=>{draft.eyes=$('eyes').value;drawEditor()};$('rotation').oninput=()=>{draft.rotation=Number($('rotation').value);$('avatarPreview').innerHTML=avatar(draft,'idle',105)};$('animate').onchange=()=>{draft.animation=$('animate').checked;drawEditor()};$('randomize').onclick=()=>{draft.shape=PRESETS[Math.floor(Math.random()*PRESETS.length)].id;draft.color=palette[Math.floor(Math.random()*palette.length)];draft.eyes=['classic','round','happy','sleepy'][Math.floor(Math.random()*4)];draft.rotation=Math.floor(Math.random()*21)-10;drawEditor()};$('botForm').onsubmit=e=>{e.preventDefault();const name=$('botName').value.trim();if(!name)return;const data={name,instructions:$('botInstructions').value,avatar:{...draft}};if(editing)Object.assign(state.bots.find(b=>b.id===editing),data);else{const id='bot-'+Date.now();state.bots.push({id,...data,status:'Ready',messages:[],model:Object.keys(models)[0],effort:'Medium',permission:'Ask approval'});state.active=id}persist();$('botDialog').close();render()};$('deleteBot').onclick=()=>{if(state.bots.length>1&&confirm('Delete this demo bot and its local messages?')){state.bots=state.bots.filter(b=>b.id!==editing);state.active=state.bots[0].id;persist();$('botDialog').close();render()}};
const pages=['General','Appearance','Accounts & Providers','Models','Usage','Personalization','Memory','Tools & MCP','Permissions','Computer Use','Routines','Data & Privacy','Advanced'];const glyphs=['⚙','◉','♙','▣','▥','☷','◐','♧','♢','▤','◷','♙','⌘'];let page='Usage';
function applyTheme(){document.body.classList.toggle('light',state.theme==='Light'||(state.theme==='System'&&matchMedia('(prefers-color-scheme: light)').matches));document.documentElement.style.setProperty('--size',({Small:'12px',Default:'14px',Large:'16px'})[state.font]||'14px')}
function settings(){ $('settingsNav').innerHTML=pages.map((n,i)=>`<button class="${n===page?'active':''}" data-page="${escapeHTML(n)}">${glyphs[i]} &nbsp; ${escapeHTML(n)}</button>`).join('');$('settingsNav').querySelectorAll('button').forEach(b=>b.onclick=()=>{page=b.dataset.page;settings()});let h=`<h2>${escapeHTML(page)}</h2>`;
if(page==='Usage'){h+='<h3 class="muted">Subscription usage · illustrative</h3>'+[['ChatGPT Plus',28,'5-hour window','#19a34a'],['ChatGPT Plus',16,'Weekly window','#19a34a'],['Claude Pro',64,'Session window','#d97706'],['Kimi Code',37,'Plan quota','#64748b']].map(([n,v,w,c])=>`<div class="quota"><div class="quota-head"><span>${n}</span><span>${v}%</span></div><div class="bar"><i style="width:${v}%;background:${c}"></i></div><small>${w}</small></div>`).join('')+'<hr><h3 class="muted">Model activity · Last 7 days</h3><div class="chart">'+[26,38,20,52,44,62,36].map((v,i)=>`<div class="chart-col"><i style="height:${v*1.6}%"></i><span>${['T2','T3','T4','T5','T6','T7','CN'][i]}</span></div>`).join('')+'</div><p class="muted">Sample usage only — no account connected.</p>'}
else if(page==='Appearance'){h+='<div class="setting-row">Theme<select id="themeSelect"><option>System</option><option>Light</option><option>Dark</option></select></div><div class="setting-row">Font size<select id="fontSelect"><option>Small</option><option>Default</option><option>Large</option></select></div>'}
else if(page==='Accounts & Providers'||page==='Models'){h+=['OpenAI / Codex','Anthropic / Claude','Google / Gemini','Kimi Code','Ollama'].map(n=>`<div class="setting-row"><span>${n}</span><small>Not connected · planned</small></div>`).join('')}
else if(page==='Data & Privacy'){h+='<p class="muted">Demo data is stored in this browser only. No remote service.</p><button id="resetDemo">Reset local demo data</button>'}
else{const rows={'General':['Language & region','Start on login','Desktop notifications','Default workspace'],'Personalization':['Global instructions','Agent personality'],'Memory':['Per-bot memory','Shared memory','Retention'],'Tools & MCP':['MCP servers','Skill management'],'Permissions':['Default access mode','Trusted folders','Approval rules','Audit history'],'Computer Use':['Execution environment','Virtual desktop','Browser profiles'],'Routines':['Active routines','Trigger settings','Execution history'],'Advanced':['Gateway endpoint','Runtime paths','Diagnostics']}[page]||[];h+=rows.map(n=>`<div class="setting-row"><span>${n}</span><small>Planned</small></div>`).join('')}
$('settingsContent').innerHTML=h;if($('themeSelect')){$('themeSelect').value=state.theme;$('themeSelect').onchange=()=>{state.theme=$('themeSelect').value;applyTheme();persist()};$('fontSelect').value=state.font;$('fontSelect').onchange=()=>{state.font=$('fontSelect').value;applyTheme();persist()}}if($('resetDemo'))$('resetDemo').onclick=()=>{if(confirm('Reset all demo data?')){localStorage.removeItem(key);location.reload()}}}
$('settingsBtn').onclick=()=>{settings();$('settingsDialog').showModal()};applyTheme();render();
